/*
 * m33_core.c
 *
 * "Safety Core 2" of the i.MX943: a completely independent instance of the
 * safe core (own FSoE master instance, own MU node, own RNG). It is released
 * by the same safe tick generated by M7.
 */

#include "flow_runtime.h"
#include "flow_log.h"

#include <string.h>

void flow_m33_core_setup (flow_runtime_t * runtime)
{
   flow_core_env_t env;

   memset (&env, 0, sizeof (env));

   env.id = MU_NODE_M33;
   env.tag = FLOW_TAG_M33;
   env.shm = runtime->shm;
   env.mu = &runtime->mu;
   env.tick = &runtime->tick;
   env.fault = &runtime->fault;
   env.cfg = &runtime->cfg;
   env.rng = &runtime->rng[MU_NODE_M33];
   env.stop = &runtime->stop;
   env.session_id = &runtime->session_id[MU_NODE_M33];
   env.session_requests = &runtime->session_requests[MU_NODE_M33];

   flow_safe_core_init (&runtime->core[MU_NODE_M33], &env);

   LOG_INFO (FLOW_TAG_M33, "M33 safety core instantiated");
}

void * flow_m33_thread (void * argument)
{
   flow_runtime_t * runtime = (flow_runtime_t *)argument;

   flow_safe_core_run (&runtime->core[MU_NODE_M33]);

   return NULL;
}
